/* Each word sits in an inline-block mask that crops it (overflow: clip is not a scroll
   container, so the view timeline still follows the page). Padding plus an equal negative
   margin leaves room for accents and descenders without changing the line height. The mask is
   the timeline; each word starts 14px of scroll after the one before it, so a line ripples up
   from left to right, scrubbed with the scroll. */
.rioproperty-rise-text-mask {
  display: inline-block;
  overflow: clip;
  vertical-align: top;
  padding-block: 0.1em 0.14em;
  margin-block: -0.1em -0.14em;
  view-timeline-name: --rioproperty-rise-text;
}

.rioproperty-rise-text-word {
  display: inline-block;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .rioproperty-rise-text-word {
      animation: rioproperty-rise-text-up linear both;
      animation-timeline: --rioproperty-rise-text;
      animation-range:
        entry calc(var(--rioproperty-rise-text-i, 0) * 14px)
        entry calc(var(--rioproperty-rise-text-distance, 360px) + var(--rioproperty-rise-text-i, 0) * 14px);
    }
    .rioproperty-rise-text-block {
      animation: rioproperty-rise-text-fade linear both;
      animation-timeline: view();
      animation-range: entry 0px entry var(--rioproperty-rise-text-distance, 360px);
    }
  }
}

@keyframes rioproperty-rise-text-up {
  from {
    transform: translateY(110%);
  }
  to {
    transform: none;
  }
}

@keyframes rioproperty-rise-text-fade {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import { Fragment, type CSSProperties, type ElementType } from "react";
import { cn } from "@foundry/foundry-utils";
import "./rioproperty-rise-text.css";

export interface RiopropertyRiseTextProps {
  /** the text; with split "words" every word rises from its own mask */
  text: string;
  /** the element to render: h2 by default */
  as?: ElementType;
  /** "words": each word rises out of a mask, a ripple from left to right (headings);
      "block": the whole text fades and rises 30px (paragraphs) */
  split?: "words" | "block";
  /** how many px of scroll, after the text enters the window, the rise takes */
  distance?: number;
  className?: string;
}

export function RiopropertyRiseText({ text, as: Tag = "h2", split = "words", distance = 360, className }: RiopropertyRiseTextProps) {
  const style = { "--rioproperty-rise-text-distance": `${distance}px` } as CSSProperties;
  if (split === "block") {
    return (
      <Tag className={cn("rioproperty-rise-text-block", className)} style={style}>
        {text}
      </Tag>
    );
  }
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <Tag className={className} style={style}>
      {words.map((word, i) => (
        <Fragment key={i}>
          <span className="rioproperty-rise-text-mask">
            <span className="rioproperty-rise-text-word" style={{ "--rioproperty-rise-text-i": i } as CSSProperties}>
              {word}
            </span>
          </span>
          {i < words.length - 1 && " "}
        </Fragment>
      ))}
    </Tag>
  );
}
